/* CCAO-F Exam Simulation question bank, set 1.
 *
 * Hand-maintained from here on; imported from the architect handoff
 * (docs/ccao-f-handoff/sim-questions-set1.json on that branch) without
 * changing any answer. Loaded after data-sim-questions-dv.js; these join the
 * same SIM_QUESTIONS pool and are kept apart by `exam`.
 *
 * Shape is the CCDV-F one (see data-sim-questions-dv.js):
 *   format       "single_select" or "multi_select"
 *   select       how many to pick; a multi-select's `correct` is an array
 *   exhibit      {lang, title, body} or null
 *   scn          always null: CCAO-F names no scenarios, so a paper is drawn
 *                by domain quota from `domains[0]`
 *   objectives   sub-skill ids AO-<guide domain>.<n>
 *   volatile     true where the answer rests on a claude.ai detail that has
 *                changed before or is likely to (docs/VERIFICATION.md)
 *   contentDate  when the question was last checked against the help center
 *
 * tests/sim-test.js checks this file's integrity alongside the other banks.
 */
SIM_QUESTIONS.push(
{"id":"AO-001","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a4"],"objectives":["AO-1.1"],"stem":"A marketing coordinator asks Claude, \"Write something about our new product,\" and gets a generic paragraph she can't use. She needs a 150-word launch email for existing customers that mentions the March 3 release date and a 15% early-bird discount. What should she do next?","exhibit":null,"options":[{"key":"A","text":"Ask again with the same request, since a second try often produces a better draft.","explanation":"Without the missing details, a retry produces another generic draft."},{"key":"B","text":"State the audience, purpose, length and the facts it must include.","explanation":"Claude can only include what it is told; the missing context is why the first draft was generic."},{"key":"C","text":"Switch to the most capable model, which will infer what a launch email needs.","explanation":"A stronger model still can't know the date, the discount or the audience."},{"key":"D","text":"Ask Claude to make the paragraph more exciting and more specific to the product.","explanation":"Asks for specifics without supplying any."}],"correct":"B","tiebreaker":"Root cause","rationale":"Vague prompts produce generic output; say who it's for, what it's for, how long, and which facts must appear.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-002","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a4"],"objectives":["AO-1.2"],"stem":"An operations analyst wants Claude to turn 40 pages of meeting notes into a quarterly review: themes, decisions made, open risks, and a one-page executive summary. One request asking for everything produces a muddled document that skips several decisions. What approach works better?","exhibit":null,"options":[{"key":"A","text":"Paste the notes again and ask Claude to be more thorough this time.","explanation":"Same overloaded request, with an instruction that doesn't change how the work is done."},{"key":"B","text":"Ask for the executive summary only, and skip the themes and decisions.","explanation":"Drops most of what the review needs."},{"key":"C","text":"Shorten the notes to 10 pages first by deleting the older meetings, then ask for everything in one request as before.","explanation":"Throws away information to fit the request instead of structuring the work."},{"key":"D","text":"Split it: extract and check decisions and risks, then summarize.","explanation":"Each step is smaller and checkable, and the summary is built from verified pieces."}],"correct":"D","tiebreaker":"Smallest thing that works","rationale":"Decompose complex requests into steps whose outputs can be checked before the next step builds on them.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-003","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a4"],"objectives":["AO-1.3"],"stem":"A recruiter's prompt for summarizing candidate interviews works well, except Claude keeps including the candidate's age and family status, which the company doesn't want in summaries. What is the best next change?","exhibit":null,"options":[{"key":"A","text":"Edit the age and family details out of each summary by hand after Claude writes it, before anyone else reads it.","explanation":"Works, but the problem recurs on every summary and relies on someone catching it."},{"key":"B","text":"Switch to a different model and hope it handles the details differently.","explanation":"Doesn't address the missing instruction."},{"key":"C","text":"Rewrite the whole prompt from scratch in a new style.","explanation":"Discards a prompt that works except for one problem."},{"key":"D","text":"Add an instruction naming what to leave out, then test it on past interviews.","explanation":"A targeted change aimed at the one failure, checked against real examples."}],"correct":"D","tiebreaker":"Root cause","rationale":"Iterate on prompts by making a targeted change for a specific failure and testing it on representative examples.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-004","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a4"],"objectives":["AO-1.4"],"stem":"A team lead wants Claude's help with two tasks: generating 20 possible names for an internal program, and analyzing last quarter's support tickets to find the three most common complaint types. How should the prompts differ?","exhibit":null,"options":[{"key":"A","text":"Use Research mode for both, since it is the most thorough option.","explanation":"Neither task needs the web; one needs creativity and the other needs the team's own data."},{"key":"B","text":"Use the same detailed prompt template for both tasks, so that the results are consistent and easy to compare later.","explanation":"Brainstorming and analysis need different instructions; one template fits neither well."},{"key":"C","text":"Ask for many varied names; for the analysis, supply the data and ask for counts with evidence.","explanation":"Brainstorming benefits from breadth; analysis needs data, method and evidence."},{"key":"D","text":"Ask for brief answers to both, since short responses are easier to review.","explanation":"Brevity starves the brainstorm and hides the analysis's reasoning."}],"correct":"C","tiebreaker":"Match the tool to the requirement","rationale":"Adapt the prompting strategy to the task type: breadth for brainstorming, data and evidence for analysis.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-005","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a4"],"objectives":["AO-1.1"],"stem":"A sales manager wants weekly pipeline summaries in the same format every time, but Claude's layout changes from week to week even though her prompt describes the format in a paragraph. What should she add?","exhibit":null,"options":[{"key":"A","text":"An example summary in exactly the layout she wants.","explanation":"A concrete example shows the format more reliably than a description."},{"key":"B","text":"A request that Claude remember the format from last week's conversation.","explanation":"Relies on earlier context that may not be available, rather than stating the format each time."},{"key":"C","text":"A longer paragraph describing the format in more detail, with every heading named.","explanation":"More description of what a single example would show directly."},{"key":"D","text":"An instruction to keep the summary as short as possible.","explanation":"Length isn't the problem; layout consistency is."}],"correct":"A","tiebreaker":"Built-in technique that targets the problem","rationale":"When output format varies, show an example of the exact format you want.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-006","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a4"],"objectives":["AO-1.2"],"stem":"A project manager is planning an office move and asks Claude for \"a complete move plan.\" The answer is long but misses the IT cutover entirely. Which TWO changes would most improve the result?","exhibit":null,"options":[{"key":"A","text":"List the workstreams the plan must cover, including IT, facilities and communications.","explanation":"Naming the parts prevents the plan from skipping one."},{"key":"B","text":"Ask Claude to draft each workstream separately, then combine them into one timeline.","explanation":"Smaller pieces get full attention, and combining them makes gaps visible."},{"key":"C","text":"Ask Claude to make the plan longer so nothing is left out.","explanation":"Length doesn't guarantee coverage; the missing workstream stays missing."},{"key":"D","text":"Ask Claude to rate how complete its plan is on a scale of 1 to 10.","explanation":"A self-rating doesn't reveal what's missing."},{"key":"E","text":"Run the same request three times and keep the longest answer.","explanation":"More of the same request, with no structure added."}],"correct":["A","B"],"tiebreaker":"The option that meets every stated goal","rationale":"Decompose by naming the required parts and drafting them separately before combining.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-007","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a4"],"objectives":["AO-1.3"],"stem":"A communications specialist's prompt produces press releases that are accurate but too formal for the company's voice. She has tried three wording changes at once, and now she can't tell which one helped. What should she do?","exhibit":null,"options":[{"key":"A","text":"Ask Claude which of the three changes it found most helpful.","explanation":"Claude's explanation of its own behavior isn't reliable evidence."},{"key":"B","text":"Write the press releases herself for now, and come back to fixing the prompt when there's more time to experiment.","explanation":"Abandons the workflow instead of improving it."},{"key":"C","text":"Keep all three changes, since the result is somewhat better.","explanation":"Keeps changes whose effect is unknown, one of which may be hurting."},{"key":"D","text":"Go back to the working prompt; change one thing at a time.","explanation":"Changing one variable at a time shows what each change actually does."}],"correct":"D","tiebreaker":"Measured beats intuitive","rationale":"Iterate one change at a time so each change's effect is visible.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-008","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a4"],"objectives":["AO-1.4"],"stem":"A policy analyst needs a balanced overview of arguments for and against a proposed remote-work policy to present to leadership. What prompting approach fits this task?","exhibit":null,"options":[{"key":"A","text":"Ask for a one-sentence summary of the policy.","explanation":"Too little to present to leadership."},{"key":"B","text":"Ask Claude which side is correct, then present that side.","explanation":"Leadership asked for a balanced overview, not a verdict."},{"key":"C","text":"Ask for the strongest case on each side, with the evidence for each.","explanation":"Matches the task: both sides, with support leadership can weigh."},{"key":"D","text":"Ask Claude to write a persuasive memo in favor of the policy, since leadership will want a clear recommendation.","explanation":"Persuasion is a different task from a balanced overview."}],"correct":"C","tiebreaker":"The option that meets every stated goal","rationale":"Match the prompt to the task: an analysis for decision-makers needs both sides and their evidence.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Prompt engineering overview","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-009","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.3"],"stem":"A benefits coordinator asks Claude to summarize the company's new parental-leave policy for an employee FAQ. Claude's summary says employees receive \"16 weeks of fully paid leave under Section 4.2.\" The FAQ will be published to 3,000 employees. What should happen before publishing?","exhibit":null,"options":[{"key":"A","text":"Publish it, since the summary cites a specific section of the policy.","explanation":"A specific-looking citation can be fabricated; specificity isn't verification."},{"key":"B","text":"Check the 16 weeks and Section 4.2 against the policy document itself.","explanation":"Claims that reach a large audience are verified against the authoritative source."},{"key":"C","text":"Ask Claude whether it is confident in the figure before publishing.","explanation":"Self-reported confidence doesn't establish accuracy."},{"key":"D","text":"Reformat the summary as a table so the numbers are easier to read.","explanation":"Better presentation of an unchecked number."}],"correct":"B","tiebreaker":"Verify before it travels","rationale":"Check specific factual claims against the source before they reach an audience; confidence and citations are not evidence.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-010","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.2"],"stem":"A market researcher asks Claude for statistics on remote-work adoption in mid-sized companies. Claude returns several precise percentages with named studies and years, but the researcher didn't provide any documents, and web search was off. How should she treat these figures?","exhibit":null,"options":[{"key":"A","text":"As possibly invented, to be checked against real sources before use.","explanation":"With no source material and no search, specific statistics may be hallucinated."},{"key":"B","text":"As reliable if Claude gives the same numbers again when she asks the question a second time in a new chat.","explanation":"A model can repeat a fabrication consistently."},{"key":"C","text":"As usable if she rounds them to the nearest 5%.","explanation":"Rounding an invented number doesn't make it real."},{"key":"D","text":"As reliable, because they come with study names and years.","explanation":"Precise details are exactly what fabricated statistics look like."}],"correct":"A","tiebreaker":"Verify before it travels","rationale":"Specific figures and citations without provided sources or search may be hallucinated; verify them before use.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-011","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.1"],"stem":"An HR generalist asks Claude to summarize a 30-page vendor contract's termination terms. The summary is accurate but leaves out a 90-day notice requirement that appears in an appendix. What does this most directly show?","exhibit":null,"options":[{"key":"A","text":"The summary has a bias problem.","explanation":"Nothing suggests a slant toward one party."},{"key":"B","text":"The summary has a formatting problem.","explanation":"Layout isn't the issue."},{"key":"C","text":"The summary has an accuracy problem.","explanation":"Everything stated is correct; nothing false was added."},{"key":"D","text":"The summary has a completeness problem.","explanation":"A required term was omitted; that's completeness, not accuracy."}],"correct":"D","tiebreaker":"Root cause","rationale":"Distinguish accuracy (what's stated is true) from completeness (nothing important is missing); check both.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-012","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.2"],"stem":"A hiring manager asks Claude to draft job descriptions for several roles. Reviewing them, she notices the engineering roles use words like \"aggressive\" and \"dominant\" while the support roles use \"nurturing\" and \"supportive.\" What should she do?","exhibit":null,"options":[{"key":"A","text":"Remove the adjectives from the engineering roles only, since those are the roles the company most wants to fill quickly.","explanation":"Fixes half the pattern."},{"key":"B","text":"Publish them, since the descriptions are well written.","explanation":"Quality of writing doesn't address the pattern she noticed."},{"key":"C","text":"Treat it as possible bias: neutralize the wording and check every description for the pattern.","explanation":"Gendered wording can discourage applicants; review and correct across the set."},{"key":"D","text":"Ask Claude to confirm that the descriptions are unbiased.","explanation":"The same model is a weak check on its own output."}],"correct":"C","tiebreaker":"Root cause","rationale":"Check outputs for bias as well as accuracy, and correct patterns across the whole set.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-013","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.4"],"stem":"A finance analyst asks Claude to explain a budget variance for two audiences: the CFO and the store managers whose budgets changed. Claude produces one explanation full of accounting terms. What should the analyst do?","exhibit":null,"options":[{"key":"A","text":"Send the same explanation to both, since it is accurate.","explanation":"Accurate isn't the same as useful to store managers."},{"key":"B","text":"Ask for two versions: a detailed one for the CFO, a plain one for store managers.","explanation":"Adapts the same facts to each audience's needs."},{"key":"C","text":"Send only the CFO version for now and let the store managers ask questions about anything they don't understand.","explanation":"Leaves the managers without an explanation they can use."},{"key":"D","text":"Ask Claude to shorten the explanation by half.","explanation":"Shorter jargon is still jargon."}],"correct":"B","tiebreaker":"The option that meets every stated goal","rationale":"Adapt outputs to the audience: the same facts, framed for what each reader needs.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-014","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a1"],"objectives":["AO-2.3"],"stem":"Which TWO situations most clearly call for human review before Claude's output is used?","exhibit":null,"options":[{"key":"A","text":"A summary of a legal contract that will be used to decide whether to renew it.","explanation":"A consequential decision rests on it; a person should check it."},{"key":"B","text":"Medication dosing information drafted for a patient handout.","explanation":"Errors could cause harm, so expert review is required."},{"key":"C","text":"Ten brainstormed names for an internal team newsletter.","explanation":"Low stakes; a quick read is enough."},{"key":"D","text":"A rephrased version of a paragraph the user wrote and can check at a glance.","explanation":"The user can verify it immediately."},{"key":"E","text":"A list of synonyms for the word \"improve.\"","explanation":"Trivial and easy to judge."}],"correct":["A","B"],"tiebreaker":"Verify before it travels","rationale":"Human review scales with the stakes: decisions, legal and health content need it; low-risk drafting doesn't.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-015","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.2"],"stem":"A project coordinator asks Claude to compare two vendor proposals that she uploaded. Claude's table says Vendor A offers 24/7 support, but in a later paragraph says Vendor A offers support \"during business hours.\" What should she do?","exhibit":null,"options":[{"key":"A","text":"Ask Claude to regenerate the comparison until the table and the paragraph agree with each other on support hours.","explanation":"Agreement isn't the same as being right."},{"key":"B","text":"Delete the paragraph so the document is consistent.","explanation":"Removes the contradiction without finding out which is true."},{"key":"C","text":"Use the table, since tables are usually more accurate than prose.","explanation":"Format doesn't make one statement more reliable than the other."},{"key":"D","text":"Check Vendor A's proposal and correct the comparison.","explanation":"An internal contradiction means at least one claim is wrong; the source settles it."}],"correct":"D","tiebreaker":"Verify before it travels","rationale":"Inconsistencies inside an output are a signal to check the source material, not to pick the more convenient claim.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-016","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.1"],"stem":"A training manager asks Claude to create a 10-question quiz from a compliance course she uploaded. How should she check the quiz before giving it to employees?","exhibit":null,"options":[{"key":"A","text":"Have one employee take the quiz and see if they pass.","explanation":"Tests difficulty, not whether the answers are correct."},{"key":"B","text":"Check each question and answer against the course, and that the main topics are covered.","explanation":"Checks both accuracy against the source and completeness of coverage."},{"key":"C","text":"Check that the quiz has exactly 10 questions, that each has four options, and that the formatting is consistent throughout.","explanation":"Structure is fine, but accuracy and coverage aren't checked."},{"key":"D","text":"Ask Claude to grade its own quiz for accuracy.","explanation":"A self-check is weaker than comparing against the source."}],"correct":"B","tiebreaker":"Verify before it travels","rationale":"Evaluate generated material against its source for both accuracy and completeness.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-017","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.4"],"stem":"A program manager asks Claude for three versions of a project status update and wants to choose the best one for a steering committee. What is the most useful way to compare them?","exhibit":null,"options":[{"key":"A","text":"Pick the longest one, since it has the most information.","explanation":"Length isn't a measure of usefulness to a committee."},{"key":"B","text":"Compare them against the committee's needs: accuracy, the decisions asked for, and length.","explanation":"Judges each version against the audience's actual needs."},{"key":"C","text":"Ask Claude which version it thinks is best.","explanation":"Hands the judgment back to the tool that produced all three."},{"key":"D","text":"Combine the best parts of all three into a single update so that nothing useful from any of the versions is lost.","explanation":"Produces a longer, repetitive update."}],"correct":"B","tiebreaker":"The option that meets every stated goal","rationale":"Compare outputs against explicit criteria drawn from the audience's needs.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-018","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.3"],"stem":"A customer-success lead uses Claude to draft responses to customer complaints. Most are routine, but some involve refunds over $1,000 or threats of legal action. What review process fits best?","exhibit":null,"options":[{"key":"A","text":"Spot-check routine replies; a person reviews high-risk ones.","explanation":"Puts human review where the stakes are."},{"key":"B","text":"Send all responses without review, since Claude writes well.","explanation":"Writing quality doesn't make high-stakes replies safe."},{"key":"C","text":"Have Claude add a disclaimer to every response instead of reviewing.","explanation":"A disclaimer doesn't catch errors."},{"key":"D","text":"Have a person review every response in full before it goes out, however routine the complaint, to be completely safe.","explanation":"Spends the same effort on low-risk and high-risk replies."}],"correct":"A","tiebreaker":"Verify before it travels","rationale":"Set human review by risk: routine output can be sampled; high-stakes output needs a person every time.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-019","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a1"],"objectives":["AO-2.2"],"stem":"Which TWO signs most strongly suggest an output may contain hallucinated content?","exhibit":null,"options":[{"key":"A","text":"It cites a specific report or statistic that wasn't in any provided material and can't be found.","explanation":"Unverifiable specifics are the classic sign of fabrication."},{"key":"B","text":"It states details that contradict the document the user provided.","explanation":"A contradiction with the source means something was invented or misread."},{"key":"C","text":"It is written in a confident, professional tone.","explanation":"Tone says nothing about accuracy."},{"key":"D","text":"It is longer than the user expected.","explanation":"Length isn't a sign of fabrication."},{"key":"E","text":"It uses bullet points instead of paragraphs.","explanation":"Formatting isn't a sign of fabrication."}],"correct":["A","B"],"tiebreaker":"Verify before it travels","rationale":"Watch for unverifiable specifics and contradictions with the source; tone and length don't indicate accuracy.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-020","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.4"],"stem":"A product manager wants Claude's competitive analysis turned into something the sales team can use during calls. The current output is five pages of prose. Which output format fits best?","exhibit":null,"options":[{"key":"A","text":"A detailed report with an appendix of sources.","explanation":"Even longer, and built for reading, not quick reference."},{"key":"B","text":"A one-page comparison table with short talking points per competitor.","explanation":"Scannable during a call, organized around what sales needs."},{"key":"C","text":"The same five pages, with the key sentences in bold.","explanation":"Still too long to use mid-call."},{"key":"D","text":"A slide deck with one competitor per slide, keeping the full paragraphs so none of the analysis's detail is lost.","explanation":"Paragraphs on slides are as hard to scan as prose."}],"correct":"B","tiebreaker":"Match the tool to the requirement","rationale":"Choose the output format for how the audience will use it.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-021","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a1"],"objectives":["AO-2.1"],"stem":"A sample exchange is shown. The analyst needs to forward the reply to regional managers. What is the most important problem to fix first?","exhibit":{"lang":"text","title":"Claude's reply","body":"Q3 sales totaled $4.1M across all regions. North contributed $1.6M,\nSouth $1.2M, and West $1.0M. North remains our strongest region, and\nWest grew fastest compared with Q2."},"options":[{"key":"A","text":"The reply should be reformatted as bullet points rather than a paragraph, since regional managers will skim it quickly.","explanation":"Formatting can wait; the content has a factual issue."},{"key":"B","text":"The regional figures add up to $3.8M, not the $4.1M total; check which is right.","explanation":"The figures contradict each other, so at least one is wrong."},{"key":"C","text":"The reply should mention the company name.","explanation":"A minor addition compared with a numerical error."},{"key":"D","text":"The tone is too casual for regional managers.","explanation":"Tone is secondary to correct numbers."}],"correct":"B","tiebreaker":"Verify before it travels","rationale":"Check that numbers in an output agree with each other and with the source before formatting or tone.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-022","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a5"],"objectives":["AO-3.2"],"stem":"An e-commerce team wants Claude to tag about 5,000 product reviews a day as positive, negative or mixed, so trends show up on a dashboard by morning. Each review is a few sentences. Which model choice fits best?","exhibit":null,"options":[{"key":"A","text":"A faster, cheaper model such as Haiku, tested first.","explanation":"Matches the model to simple, high-volume work, with a quick quality check."},{"key":"B","text":"Alternating between models at random to balance the cost.","explanation":"Adds inconsistency without matching the task."},{"key":"C","text":"Whichever model is set as the default, since model choice doesn't affect cost.","explanation":"Model choice is one of the main cost and speed levers."},{"key":"D","text":"The most capable model, so every tag is as accurate as possible, since the dashboard drives decisions for the whole business.","explanation":"Pays for reasoning the task doesn't need, at higher cost and latency."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Match the model to the task: lighter, faster models for simple high-volume work; more capable models for complex reasoning.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Models overview","url":"https://platform.claude.com/docs/en/about-claude/models/overview","type":"docs"}],"note":"Model names change between generations; the tiers (Haiku fastest and lowest cost, Opus most capable, Sonnet between) are what the guide tests.","volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-023","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a5"],"objectives":["AO-3.2"],"stem":"A strategy consultant is working through a complex market-entry analysis with many interacting factors and needs the most careful reasoning available. Time and cost per request matter less here. Which model choice fits?","exhibit":null,"options":[{"key":"A","text":"The same model used for routine email drafting, for consistency.","explanation":"Consistency with an unrelated task isn't a reason to pick a model."},{"key":"B","text":"Any model, since they all reason equally well.","explanation":"Tiers differ in capability, speed and cost."},{"key":"C","text":"The fastest, lowest-cost model, since it responds quickest.","explanation":"Optimizes for speed the consultant said matters less."},{"key":"D","text":"A more capable model, such as Opus, suited to complex reasoning work.","explanation":"The task's complexity is what the most capable tier is for."}],"correct":"D","tiebreaker":"Match the tool to the requirement","rationale":"Choose a more capable model when task complexity justifies the extra cost and time.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Models overview","url":"https://platform.claude.com/docs/en/about-claude/models/overview","type":"docs"}],"note":null,"volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-024","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a5"],"objectives":["AO-3.1"],"stem":"An analyst needs a briefing on how three competitors have changed their pricing over the past year, drawing on current public sources with citations she can check. Which Claude feature fits best?","exhibit":null,"options":[{"key":"A","text":"A Project with last year's pricing PDFs uploaded.","explanation":"Last year's documents miss the past year's changes."},{"key":"B","text":"A regular chat with web search off, asking Claude what it knows.","explanation":"Without search, Claude can't reach current sources and may be out of date."},{"key":"C","text":"Research, which runs multiple searches and returns a cited report.","explanation":"Built for multi-source investigation with checkable citations."},{"key":"D","text":"An artifact, so the briefing appears in a separate window.","explanation":"Artifacts present output; they don't gather sources."}],"correct":"C","tiebreaker":"Match the tool to the requirement","rationale":"Use Research for current, multi-source questions that need citations.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Use research on Claude","url":"https://support.claude.com/en/articles/11088861-use-research-on-claude","type":"docs"}],"note":null,"volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-025","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a5"],"objectives":["AO-3.1"],"stem":"A trainer works with Claude every week on the same onboarding program: the same curriculum documents, the same tone guidelines, the same audience. Today she re-uploads the documents and re-explains the guidelines in every new chat. What should she use?","exhibit":null,"options":[{"key":"A","text":"A Project with documents and instructions.","explanation":"Persistent context for recurring work, without repeating setup each time."},{"key":"B","text":"One very long chat that she keeps returning to for every task, so all the earlier context stays in one place for Claude.","explanation":"A single long chat eventually hits context limits and mixes unrelated work."},{"key":"C","text":"Research mode, so Claude looks up the curriculum each time.","explanation":"The curriculum is internal; Research searches the web."},{"key":"D","text":"An artifact containing the guidelines, opened in each chat.","explanation":"Artifacts are outputs, not persistent context."}],"correct":"A","tiebreaker":"Built-in feature over workaround","rationale":"Use Projects for recurring work that needs the same documents and instructions every time.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-026","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a5"],"objectives":["AO-3.3"],"stem":"After a two-hour working session in one chat, a consultant notices Claude has started forgetting details she gave early on and contradicting earlier decisions. What should she do?","exhibit":null,"options":[{"key":"A","text":"Have Claude summarize the key decisions, then start a new chat with that summary.","explanation":"A fresh context with the essentials restores focus."},{"key":"B","text":"Switch to the fastest model to process the long chat quicker.","explanation":"Speed doesn't fix a crowded context."},{"key":"C","text":"Delete her earliest messages so the chat is shorter.","explanation":"Removes the very details Claude is losing."},{"key":"D","text":"Keep going in the same chat and remind Claude of each forgotten detail as soon as it comes up again in the work.","explanation":"Patches symptoms while the conversation keeps growing."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"Manage context limits by summarizing and restarting, or by persisting key information somewhere durable.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-027","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a5"],"objectives":["AO-3.1"],"stem":"A marketing lead wants Claude to build a one-page interactive budget calculator she can tweak and share with her team. Which TWO features are most relevant?","exhibit":null,"options":[{"key":"A","text":"Artifacts, which display standalone content such as an interactive page alongside the chat.","explanation":"Artifacts are built for creating and iterating on standalone outputs like this."},{"key":"B","text":"Iterating on the artifact in the same chat, asking Claude for changes as she tests it.","explanation":"Revising the artifact in place is how it gets refined."},{"key":"C","text":"Research mode, so Claude can find budget calculators online.","explanation":"She wants her own tool built, not a search."},{"key":"D","text":"The fastest model, because calculators are simple.","explanation":"Model choice isn't the main factor; the feature is."},{"key":"E","text":"Incognito chat, so the calculator isn't saved.","explanation":"She wants to keep and share it."}],"correct":["A","B"],"tiebreaker":"Match the tool to the requirement","rationale":"Use artifacts for standalone outputs like documents, pages and tools, and iterate on them in place.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-028","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a5"],"objectives":["AO-3.3"],"stem":"A paralegal regularly references the same 2,000-page set of case documents. She wants Claude to draw on them across many conversations over several months. Which approach handles this best?","exhibit":null,"options":[{"key":"A","text":"Summarize all 2,000 pages into one paragraph and paste that instead.","explanation":"Loses the detail she needs to reference."},{"key":"B","text":"Paste the relevant pages into each new chat as needed.","explanation":"Repetitive, and it's easy to miss the relevant pages."},{"key":"C","text":"Put the documents in a Project's knowledge.","explanation":"Persistent knowledge for recurring work; on paid plans large knowledge bases are searched rather than loaded whole."},{"key":"D","text":"Rely on Claude's memory to retain the documents from earlier chats, since memory carries context between conversations.","explanation":"Memory keeps useful context about you and your work, not a full document library."}],"correct":"C","tiebreaker":"Built-in feature over workaround","rationale":"Persist large, recurring reference material as Project knowledge rather than re-pasting it.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"},{"title":"RAG for projects","url":"https://support.claude.com/en/articles/11473015-retrieval-augmented-generation-rag-for-projects","type":"docs"}],"note":null,"volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-029","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.1"],"stem":"A department head asks an associate to \"use Claude to fix our slow invoice-approval process.\" Before designing anything, what should the associate do first?","exhibit":null,"options":[{"key":"A","text":"Write prompts for each approval step right away.","explanation":"Builds a solution before understanding the problem."},{"key":"B","text":"Map the current process and find where the delays actually happen first.","explanation":"You can't decide where Claude helps until you know where time is lost."},{"key":"C","text":"Choose the most capable model for the project.","explanation":"Model choice comes after knowing the task."},{"key":"D","text":"Announce to the team that Claude will handle approvals from now on.","explanation":"Commits to a solution that hasn't been designed or tested."}],"correct":"B","tiebreaker":"Root cause","rationale":"Start solution design by analyzing the requirement and the current process before choosing where Claude fits.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-030","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.4"],"stem":"A director asks whether Claude can \"replace our analysts' quarterly reports entirely.\" The associate has seen Claude draft strong first versions but also make occasional numerical errors. What is the most accurate thing to tell the director?","exhibit":null,"options":[{"key":"A","text":"No, Claude isn't useful for reports.","explanation":"Understates the value already seen."},{"key":"B","text":"Claude can speed up drafting, but analysts still verify figures and own the conclusions.","explanation":"Explains the value and the limitation honestly."},{"key":"C","text":"Claude will become accurate enough to replace the analysts within a few months, so plan the transition for next year.","explanation":"A prediction the associate has no basis for."},{"key":"D","text":"Yes, Claude can fully replace the analysts.","explanation":"Overstates what's been shown and ignores the error rate."}],"correct":"B","tiebreaker":"The option that meets every stated goal","rationale":"Communicate Claude's value and limits honestly: where it helps, and where people stay accountable.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-031","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.3"],"stem":"A sales operations team wants Claude to draft weekly account summaries from CRM exports. Which workflow design is most dependable?","exhibit":null,"options":[{"key":"A","text":"Reps write summaries themselves and ask Claude to fix typos.","explanation":"Uses Claude for very little of the work it could help with."},{"key":"B","text":"Claude drafts summaries from memory, without the CRM export.","explanation":"Without data, the summaries can't be accurate."},{"key":"C","text":"Claude drafts from the export; a rep reviews before sending.","explanation":"Claude does the drafting and a person checks before it goes out."},{"key":"D","text":"Claude writes the summaries and sends them straight to clients with no review, which saves the reps the most time each week.","explanation":"Errors reach clients unchecked."}],"correct":"C","tiebreaker":"The option that meets every stated goal","rationale":"Design workflows where Claude handles drafting from real data and people review before output reaches customers.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-032","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a2"],"objectives":["AO-4.2"],"stem":"An event planner is organizing a 200-person conference and wants Claude's help. Which TWO uses of Claude fit planning work best?","exhibit":null,"options":[{"key":"A","text":"Drafting a task timeline working backward from the event date, for her to review.","explanation":"Planning support that she checks and adjusts."},{"key":"B","text":"Generating a checklist of logistics categories to consider, such as catering, AV and accessibility.","explanation":"Helps surface items she might miss."},{"key":"C","text":"Signing the venue contract on her behalf.","explanation":"Claude can't take on commitments for her."},{"key":"D","text":"Guaranteeing that attendance will reach 200.","explanation":"No tool can guarantee an outcome like that."},{"key":"E","text":"Choosing the final budget without her input.","explanation":"Budget decisions are hers to make."}],"correct":["A","B"],"tiebreaker":"The option that meets every stated goal","rationale":"Use Claude to support research and planning, with people making the commitments and decisions.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-033","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.5"],"stem":"A knowledge manager wants Claude to turn a messy folder of 50 meeting notes into something the team can search for past decisions. Which output is most useful?","exhibit":null,"options":[{"key":"A","text":"One long narrative summary covering all 50 meetings in order, so the full story of every discussion is kept together.","explanation":"Hard to search for a specific decision."},{"key":"B","text":"A table of decisions with date, owner, meeting and a one-line note.","explanation":"Organized around how the team will look things up."},{"key":"C","text":"A word cloud of the most common terms.","explanation":"Shows topics, not decisions."},{"key":"D","text":"Fifty separate summaries, one per meeting.","explanation":"Still requires reading each to find a decision."}],"correct":"B","tiebreaker":"Match the tool to the requirement","rationale":"Organize information in the format that matches how people will use it.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-034","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.3"],"stem":"A support manager piloted Claude for drafting replies and found it saves time on simple tickets but struggles with tickets that need account-specific history. What is the best next step?","exhibit":null,"options":[{"key":"A","text":"Use Claude on simple tickets now, and route or give it history for the rest.","explanation":"Uses Claude where it works and addresses the gap directly."},{"key":"B","text":"Use Claude for all tickets and accept the errors.","explanation":"Knowingly sends weaker replies."},{"key":"C","text":"Wait for a newer, more capable model before using Claude for anything, so the team only has to change its process once.","explanation":"Delays the value already demonstrated."},{"key":"D","text":"Stop using Claude, since it doesn't handle every ticket.","explanation":"Gives up the proven time savings on simple tickets."}],"correct":"A","tiebreaker":"Smallest thing that works","rationale":"Iterate on a solution design: keep what works, and address the specific gap a pilot reveals.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-035","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.1"],"stem":"A finance team asks for \"AI to help with month-end close.\" Which question should the associate ask first to shape the solution?","exhibit":null,"options":[{"key":"A","text":"How many people are on the finance team, and how comfortable are they with using new software tools day to day?","explanation":"Relevant later, but it doesn't define the use case."},{"key":"B","text":"What color scheme should reports use?","explanation":"A presentation detail, not a requirement."},{"key":"C","text":"Which model is the newest?","explanation":"Model choice comes after understanding the work."},{"key":"D","text":"Which month-end tasks take the most time, and what goes in and out?","explanation":"Identifies where Claude can help and what it would need."}],"correct":"D","tiebreaker":"Root cause","rationale":"Analyze the use case first: where the time goes and what the task's inputs and outputs are.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-036","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.4"],"stem":"A team lead is presenting a Claude pilot to skeptical executives. Which presentation approach is most credible?","exhibit":null,"options":[{"key":"A","text":"Promise the pilot will cut costs by half.","explanation":"An unsupported promise."},{"key":"B","text":"Show the three best outputs from the pilot.","explanation":"Cherry-picked results hide the real performance."},{"key":"C","text":"Show measured results, such as time saved and errors, plus known limits.","explanation":"Evidence plus honest limits builds trust."},{"key":"D","text":"Explain how advanced the underlying model is, and how it compares with competing products on public benchmarks.","explanation":"Capability claims don't show results for this team."}],"correct":"C","tiebreaker":"Measured beats intuitive","rationale":"Communicate value with measured results and stated limitations, not highlights or promises.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-037","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.2"],"stem":"An operations analyst wants to improve the company's employee onboarding process with Claude's help. Which use of Claude is most likely to produce real improvement?","exhibit":null,"options":[{"key":"A","text":"Asking Claude to write a new onboarding process from scratch, with nothing about the current one.","explanation":"Generic output that ignores the company's actual situation."},{"key":"B","text":"Give Claude the current steps and new-hire feedback, and ask for bottlenecks and changes to test.","explanation":"Grounds the analysis in real data and produces testable changes."},{"key":"C","text":"Asking Claude to rate the current process from 1 to 10.","explanation":"A score without analysis doesn't show what to change."},{"key":"D","text":"Asking Claude to make the onboarding handbook longer and more detailed.","explanation":"More content isn't the same as a better process."}],"correct":"B","tiebreaker":"Root cause","rationale":"Use Claude for process improvement by grounding it in the current process and real feedback.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-038","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a2"],"objectives":["AO-4.5"],"stem":"A sales director asks Claude to analyze regional revenue trends for a board presentation. The board will see the result for under a minute. Which output format fits best?","exhibit":null,"options":[{"key":"A","text":"A simple trend chart with two or three headline takeaways.","explanation":"Matches the time the audience has."},{"key":"B","text":"A spreadsheet of the raw data.","explanation":"Leaves the board to do the analysis."},{"key":"C","text":"A list of every data point with its source.","explanation":"Detail belongs in an appendix, not the main view."},{"key":"D","text":"A detailed written analysis of every region, so board members can see the full picture behind each number.","explanation":"Too much to absorb in under a minute."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Choose the output format for the audience and the time they have.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-039","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a6"],"objectives":["AO-5.1"],"stem":"A legal operations team set up a Project for contract reviews. Every chat should follow the same review checklist and use a formal tone. Where should the checklist and tone guidance go?","exhibit":null,"options":[{"key":"A","text":"In a document emailed to the team.","explanation":"Claude never sees it."},{"key":"B","text":"In the name of the Project.","explanation":"A name can't carry a checklist."},{"key":"C","text":"In the Project instructions, which apply to every chat in it.","explanation":"Project instructions apply across all of the Project's chats."},{"key":"D","text":"At the start of each new chat, typed in by whoever starts it, so everyone sees the checklist before they begin.","explanation":"Depends on everyone remembering, and versions drift."}],"correct":"C","tiebreaker":"Built-in feature over workaround","rationale":"Put guidance that should apply to every chat in the Project instructions.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-040","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a6"],"objectives":["AO-5.2"],"stem":"A product manager adds a Google Doc to her Project through the Google Drive connector. The doc contains a pricing table pasted as an image. Claude answers questions about the doc's text correctly but says it can't find any pricing figures. What is the most likely reason?","exhibit":null,"options":[{"key":"A","text":"The doc must be shared publicly, or at least with the whole company, before Claude is allowed to read all of it.","explanation":"Claude already read its text through her access."},{"key":"B","text":"It reads the text, not embedded images.","explanation":"Content that exists only as an image isn't extracted."},{"key":"C","text":"The Project has too many documents, so Claude skipped this one.","explanation":"Claude answered from this doc's text, so it wasn't skipped."},{"key":"D","text":"Claude doesn't understand pricing tables.","explanation":"Claude reads tables fine when they're text."}],"correct":"B","tiebreaker":"Root cause","rationale":"Know what each knowledge source passes to Claude; content only in images may not come through a connector.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Use Google Workspace connectors","url":"https://support.claude.com/en/articles/10166901-use-google-workspace-connectors","type":"docs"}],"note":"Per the Google Workspace connector article as of November 2026. Re-check if connector behavior changes.","volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-041","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a6"],"objectives":["AO-5.4"],"stem":"A Project's knowledge base includes last year's pricing sheet and this year's pricing sheet. Customers have been quoted old prices. What should the Project owner do?","exhibit":null,"options":[{"key":"A","text":"Add a third document to the knowledge base explaining which of the two pricing sheets is the current one to use.","explanation":"Leaves the outdated sheet where Claude can still use it."},{"key":"B","text":"Remove or archive last year's sheet.","explanation":"Keeps the configuration current at the source of the problem."},{"key":"C","text":"Tell users to double-check every price Claude gives.","explanation":"Pushes the problem onto every user, every time."},{"key":"D","text":"Rename this year's file with \"FINAL\" in capitals.","explanation":"A naming hint doesn't stop Claude from using the old sheet."}],"correct":"B","tiebreaker":"Root cause","rationale":"Maintain configurations over time: remove or archive outdated knowledge rather than layering corrections on top.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-042","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a6"],"objectives":["AO-5.3"],"stem":"A team lead wants every chat in the team's Project to start from the same rules: cite which document an answer came from, say when the documents don't cover a question, and never guess at figures. How should she write these instructions?","exhibit":null,"options":[{"key":"A","text":"As a single sentence: \"Be accurate.\"","explanation":"Too vague to change behavior."},{"key":"B","text":"As a reminder each user types at the end of their questions.","explanation":"Inconsistent, and easy to forget."},{"key":"C","text":"As a long essay in the Project instructions on why accuracy matters to the team, without listing any specific rules.","explanation":"Explains values without telling Claude what to do."},{"key":"D","text":"As specific rules in the Project instructions, with an example answer.","explanation":"Specific, persistent instructions with an example are applied consistently."}],"correct":"D","tiebreaker":"Built-in technique that targets the problem","rationale":"Write system-level instructions as specific rules, with an example, in the place that applies them every time.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-043","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a6"],"objectives":["AO-5.2"],"stem":"An executive assistant connects Claude to the executive's Gmail and Calendar to help manage scheduling. Which TWO practices are most appropriate?","exhibit":null,"options":[{"key":"A","text":"Keep the default that asks for approval before Claude takes an action such as sending an email.","explanation":"Approval keeps a person in control of actions taken on the executive's behalf."},{"key":"B","text":"Connect only the services the task needs.","explanation":"Limits access to what the work requires."},{"key":"C","text":"Connect every available service, in case it's useful later.","explanation":"Grants access the task doesn't need."},{"key":"D","text":"Share the executive's account password with Claude in a chat message.","explanation":"Connectors use proper authorization; passwords never go in chats."},{"key":"E","text":"Turn off approvals so Claude can work faster.","explanation":"Removes the check on actions taken on someone else's behalf."}],"correct":["A","B"],"tiebreaker":"Guaranteed beats likely","rationale":"Manage connectors with least access and keep approval for actions taken on someone's behalf.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Use Google Workspace connectors","url":"https://support.claude.com/en/articles/10166901-use-google-workspace-connectors","type":"docs"}],"note":null,"volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-044","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a6"],"objectives":["AO-5.1"],"stem":"A sales enablement lead creates a Project for proposal writing. Which TWO items belong in the Project's knowledge?","exhibit":null,"options":[{"key":"A","text":"The company's current product catalog and approved pricing.","explanation":"Reference material every proposal draws on."},{"key":"B","text":"Two or three strong past proposals as examples of the expected style.","explanation":"Examples show Claude what good looks like."},{"key":"C","text":"Every email the sales team has sent in the past five years.","explanation":"Mostly irrelevant, and may include sensitive data."},{"key":"D","text":"Competitors' confidential documents obtained without permission.","explanation":"Inappropriate to use at all."},{"key":"E","text":"A note asking Claude to try its best.","explanation":"Not useful knowledge."}],"correct":["A","B"],"tiebreaker":"Signal beats volume","rationale":"Put focused, relevant, current reference material and examples into Project knowledge.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-045","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a6"],"objectives":["AO-5.4"],"stem":"A team's Project instructions were written six months ago. Since then, the team has changed its report template and its approval process. Users report that Claude's drafts follow the old template. What should happen?","exhibit":null,"options":[{"key":"A","text":"Users should paste the new template into every chat.","explanation":"Works around an outdated configuration every time."},{"key":"B","text":"Update the Project's instructions and knowledge to match, then test a few drafts.","explanation":"Fixes the configuration and checks the result."},{"key":"C","text":"Create a new Project for the new template and leave the old one in place, so that past chats remain available.","explanation":"Two Projects with conflicting guidance invite confusion."},{"key":"D","text":"Ask Claude to guess which template is newer.","explanation":"Guessing isn't a fix."}],"correct":"B","tiebreaker":"Root cause","rationale":"Keep Project configurations current as processes change, and test after updating.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-046","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a3"],"objectives":["AO-6.2"],"stem":"A payroll specialist wants Claude to find which departments drive overtime costs. The export she has includes employee names, Social Security numbers and pay rates. Company policy bans sending government ID numbers to any AI tool. What should she do?","exhibit":null,"options":[{"key":"A","text":"Strip the ID numbers and names, keep department, hours and pay, then upload.","explanation":"Overtime by department doesn't need identities, so the analysis proceeds within policy."},{"key":"B","text":"Upload it and ask Claude not to remember the ID numbers.","explanation":"An instruction to Claude doesn't satisfy a data-handling policy."},{"key":"C","text":"Upload it in an incognito chat so it isn't saved.","explanation":"Not saving the chat doesn't change that the data was shared against policy."},{"key":"D","text":"Upload the export as-is, since the analysis is for internal use only and nobody outside the company will see it.","explanation":"Internal use doesn't exempt the data from policy."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Remove or anonymize regulated data before it reaches the tool; instructions to the model don't satisfy policy.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24","family":"anonymize-first"},
{"id":"AO-047","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a3"],"objectives":["AO-6.1"],"stem":"Which TWO uses of Claude are inappropriate without additional controls?","exhibit":null,"options":[{"key":"A","text":"Making final hiring decisions about candidates with no human involvement.","explanation":"Consequential decisions about people need human judgment and accountability."},{"key":"B","text":"Giving customers legally binding answers about contract terms without review.","explanation":"Binding legal statements need review by qualified people."},{"key":"C","text":"Drafting a first version of an internal newsletter.","explanation":"Low risk, and a person reviews before sending."},{"key":"D","text":"Brainstorming names for a team offsite.","explanation":"Low risk."},{"key":"E","text":"Summarizing a public article for personal learning.","explanation":"Low risk."}],"correct":["A","B"],"tiebreaker":"Eliminate what the scenario rules out","rationale":"Identify high-risk use cases (consequential decisions about people, binding statements) that require human oversight.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-048","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a3"],"objectives":["AO-6.3"],"stem":"An employee finds that a free AI tool not approved by her company gives faster answers than the company's approved Claude workspace. She wants to use it for client work. What should she do?","exhibit":null,"options":[{"key":"A","text":"Use both and compare which answers are better.","explanation":"Still sends client work to an unapproved tool."},{"key":"B","text":"Use the free tool, since it gives faster answers.","explanation":"Bypasses the organization's AI policy and its data protections."},{"key":"C","text":"Keep using the approved workspace and raise the speed issue properly.","explanation":"Follows policy and gets the concern heard."},{"key":"D","text":"Use the free tool, but only for the parts of the client work that aren't confidential, and keep the rest in the approved one.","explanation":"Still sends client work through an unapproved tool."}],"correct":"C","tiebreaker":"Eliminate what the scenario rules out","rationale":"Follow organizational AI policy on approved tools, and raise concerns through proper channels rather than working around it.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-049","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a3"],"objectives":["AO-6.2"],"stem":"A healthcare administrator wants Claude to help draft letters to patients about their appointment changes. What is the most important consideration before starting?","exhibit":null,"options":[{"key":"A","text":"Whether Claude can match the clinic's existing letter template, including its logo, header and standard sign-off.","explanation":"A formatting concern, secondary to privacy."},{"key":"B","text":"Whether policy and regulations allow patient data to be used with this tool, and how.","explanation":"Patient data is regulated; that question comes first."},{"key":"C","text":"Which model writes the most friendly letters.","explanation":"Tone is secondary to compliance."},{"key":"D","text":"How many letters Claude can produce per hour.","explanation":"Throughput doesn't matter if the use isn't permitted."}],"correct":"B","tiebreaker":"Eliminate what the scenario rules out","rationale":"Check regulatory and policy requirements before using sensitive personal data with AI tools.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-050","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a3"],"objectives":["AO-6.4"],"stem":"A marketing team wants to publish customer testimonials that Claude writes in the voice of satisfied customers, attributed to invented people. What is the main problem?","exhibit":null,"options":[{"key":"A","text":"Presenting invented testimonials as real customers' words is deceptive.","explanation":"It misleads readers about who said what."},{"key":"B","text":"Claude may not match the brand voice.","explanation":"A style concern beside a deception problem."},{"key":"C","text":"The testimonials need a stronger call to action at the end of each one, so readers know what to do next.","explanation":"Not the issue."},{"key":"D","text":"The testimonials might be too long.","explanation":"Length isn't the issue."}],"correct":"A","tiebreaker":"Eliminate what the scenario rules out","rationale":"Consider the ethics of AI-generated content: presenting invented statements as real people's is deceptive.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-051","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a3"],"objectives":["AO-6.2"],"stem":"A consultant wants Claude to help prepare for a client meeting using the client's confidential financial statements. Her firm's policy allows confidential client data only in the firm's approved Team workspace. What should she do?","exhibit":null,"options":[{"key":"A","text":"Retype the key figures from memory into any account.","explanation":"Still shares confidential data, and adds transcription errors."},{"key":"B","text":"Ask the client to send the statements directly to Claude.","explanation":"Doesn't change where the data goes or which policy applies."},{"key":"C","text":"Use her personal Claude account, since it's faster to access.","explanation":"A personal account falls outside the firm's approved environment."},{"key":"D","text":"Use the firm's approved Team workspace, as the policy requires.","explanation":"Uses the environment the policy approved for this data."}],"correct":"D","tiebreaker":"Eliminate what the scenario rules out","rationale":"Use only the environments organizational policy approves for confidential data.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-052","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a3"],"objectives":["AO-6.1"],"stem":"A manager asks Claude to write performance reviews for her direct reports, giving it only their names and job titles. What is the core problem with this use?","exhibit":null,"options":[{"key":"A","text":"Performance reviews should be written in the HR system's spreadsheet template, not as free text in a chat with Claude.","explanation":"Format isn't the issue."},{"key":"B","text":"Claude will write reviews that are too short.","explanation":"Length isn't the problem."},{"key":"C","text":"The reviews would be invented, since Claude knows nothing of each person's work.","explanation":"Reviews affect people's careers and must reflect real performance."},{"key":"D","text":"Claude can't use a professional tone.","explanation":"Tone isn't the issue."}],"correct":"C","tiebreaker":"Eliminate what the scenario rules out","rationale":"Recognize inappropriate uses: content about real people's performance can't be generated without real information and the manager's judgment.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-053","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a3"],"objectives":["AO-6.3"],"stem":"An organization's AI policy says AI-assisted content sent to clients must be reviewed by a person and disclosed according to the client's contract terms. A colleague asks whether she can skip the review because the content is \"just a summary.\" What is the right answer?","exhibit":null,"options":[{"key":"A","text":"Yes, summaries are exempt because they are short.","explanation":"The policy doesn't exempt summaries."},{"key":"B","text":"No, the policy covers AI-assisted client content, summaries included.","explanation":"Policy applies as written; a summary is still client content."},{"key":"C","text":"Yes, as long as Claude marks the summary as accurate and the colleague adds a note saying it was checked by AI.","explanation":"Self-marking isn't review."},{"key":"D","text":"Only if the client won't read it carefully.","explanation":"That isn't a policy exception."}],"correct":"B","tiebreaker":"Eliminate what the scenario rules out","rationale":"Apply organizational AI policies as written, without inventing exceptions.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-054","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a3"],"objectives":["AO-6.2"],"stem":"An analyst wants to use Claude to find trends in employee survey comments that include names and identifying details. Which TWO steps best protect privacy while still allowing the analysis?","exhibit":null,"options":[{"key":"A","text":"Remove names and identifying details from the comments before sharing them.","explanation":"Trends don't need identities."},{"key":"B","text":"Confirm that company policy allows this survey data to be used with Claude.","explanation":"Policy determines whether and how the data may be used."},{"key":"C","text":"Ask Claude to promise not to read the names.","explanation":"An instruction doesn't protect the data."},{"key":"D","text":"Share the comments, then delete the chat afterward.","explanation":"The data was still shared."},{"key":"E","text":"Use the fastest model so the data is processed quickly.","explanation":"Speed is unrelated to privacy."}],"correct":["A","B"],"tiebreaker":"Guaranteed beats likely","rationale":"Protect privacy with policy checks and de-identification before sharing, not instructions after.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24","family":"anonymize-first"},
{"id":"AO-055","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a7"],"objectives":["AO-7.1"],"stem":"A team's prompt for summarizing customer calls worked well for months. This week, summaries started missing the customer's main request. Nothing changed in the prompt, but the call transcripts now come from a new recording tool. Where should the team look first?","exhibit":null,"options":[{"key":"A","text":"At switching to the most capable model.","explanation":"Doesn't address what changed."},{"key":"B","text":"At retraining the team to write the call summaries by hand until the prompt can be rebuilt and tested again.","explanation":"Abandons a workflow that worked until the input changed."},{"key":"C","text":"At the new transcripts, to see whether their format or content changed.","explanation":"The only thing that changed is the input."},{"key":"D","text":"At rewriting the prompt from scratch.","explanation":"The prompt worked for months; the input changed."}],"correct":"C","tiebreaker":"Root cause","rationale":"Diagnose by finding what changed; when the prompt is unchanged, look at the inputs.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-056","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a7"],"objectives":["AO-7.2"],"stem":"A content writer is tuning a prompt for product descriptions. Reviewers say the descriptions are too long and too technical. What is the best way to adjust?","exhibit":null,"options":[{"key":"A","text":"Ask the reviewers to accept longer descriptions.","explanation":"Ignores the feedback."},{"key":"B","text":"Change the length instruction and the reading-level instruction at the same time, then judge the result.","explanation":"If the result changes, she won't know which change did it."},{"key":"C","text":"Change one instruction, test it on the same set of products, then make the next change.","explanation":"Isolates each change's effect."},{"key":"D","text":"Switch models and see whether the descriptions improve.","explanation":"Changes everything at once, without addressing the feedback directly."}],"correct":"C","tiebreaker":"Measured beats intuitive","rationale":"Adjust based on feedback by changing one variable at a time and retesting on the same examples.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-057","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a7"],"objectives":["AO-7.3"],"stem":"A team uses Claude to produce a weekly report through five separate chats, copying output between them by hand. It takes two hours a week. What is the best first optimization?","exhibit":null,"options":[{"key":"A","text":"Move the steps into a Project with standard instructions and reusable prompts.","explanation":"Reduces repeated setup and copying without adding complexity."},{"key":"B","text":"Add three more review steps to catch errors.","explanation":"Adds time without addressing the inefficiency."},{"key":"C","text":"Hire an engineer to build a custom application that connects all five steps and runs the whole report automatically.","explanation":"Far more complexity than a weekly report needs."},{"key":"D","text":"Switch to a faster model.","explanation":"Speed of generation isn't where the two hours go."}],"correct":"A","tiebreaker":"Smallest thing that works","rationale":"Optimize workflows by removing repeated manual steps with the simplest effective change.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"What are projects?","url":"https://support.claude.com/en/articles/9517075-what-are-projects","type":"docs"}],"note":null,"volatile":false,"contentDate":"2026-11-24"},
{"id":"AO-058","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a7"],"objectives":["AO-7.1"],"stem":"A user turned on Research and asked a question that needs current information, but Claude answered without searching the web. What should the user check first?","exhibit":null,"options":[{"key":"A","text":"Whether the question is too long or too broad for Research, which works best on short, narrowly scoped questions.","explanation":"Length isn't why it wouldn't search."},{"key":"B","text":"Whether a more capable model is selected.","explanation":"Model choice doesn't turn searching on."},{"key":"C","text":"Whether the chat is inside a Project.","explanation":"Being in a Project doesn't block searching."},{"key":"D","text":"Whether web search is turned on, since Research needs it.","explanation":"Research relies on web search being enabled."}],"correct":"D","tiebreaker":"The mechanism's own contract","rationale":"Troubleshoot features by checking their prerequisites; Research depends on web search being on.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Use research on Claude","url":"https://support.claude.com/en/articles/11088861-use-research-on-claude","type":"docs"}],"note":"Per the Research support article as of November 2026.","volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-059","exam":"CCAO-F","set":"ao_set1","format":"multi_select","select":2,"scn":null,"domains":["a7"],"objectives":["AO-7.1"],"stem":"A user enabled a custom skill her team uses to format proposals, but Claude never seems to use it. Her colleagues' setups work. Which TWO things are most worth checking?","exhibit":null,"options":[{"key":"A","text":"Whether code execution and file creation are enabled in her settings, since skills depend on them.","explanation":"Skills run in Claude's code environment and need it switched on."},{"key":"B","text":"Whether the skill is toggled on in her own skills list.","explanation":"Each user's list controls which skills Claude can use."},{"key":"C","text":"Whether her proposals are too short.","explanation":"Unrelated to whether the skill loads."},{"key":"D","text":"Whether she is using the newest browser.","explanation":"Unlikely to be the cause."},{"key":"E","text":"Whether she has typed the skill's name in capital letters.","explanation":"Claude decides when to use a skill from its description."}],"correct":["A","B"],"tiebreaker":"The mechanism's own contract","rationale":"When a feature works for others but not for one user, check that user's settings and prerequisites.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"},{"title":"Use skills in Claude","url":"https://support.claude.com/en/articles/12512180-use-skills-in-claude","type":"docs"}],"note":null,"volatile":true,"contentDate":"2026-11-24"},
{"id":"AO-060","exam":"CCAO-F","set":"ao_set1","format":"single_select","select":1,"scn":null,"domains":["a7"],"objectives":["AO-7.3"],"stem":"A recruiting team uses Claude to screen résumés against job requirements. To save time, a manager proposes having Claude also send rejection emails automatically, with no review. What is the best response?","exhibit":null,"options":[{"key":"A","text":"Send the rejections automatically, but only on weekends, so candidates hear back quickly without bothering the recruiters.","explanation":"Timing doesn't change the risk."},{"key":"B","text":"Do it, since it saves the most time.","explanation":"Removes oversight from a decision that affects candidates."},{"key":"C","text":"Keep a person reviewing screens and rejections; save time on lower-risk steps.","explanation":"Optimizes without removing human judgment from consequential decisions."},{"key":"D","text":"Stop using Claude for screening entirely.","explanation":"Discards the time already saved on lower-risk work."}],"correct":"C","tiebreaker":"The option that meets every stated goal","rationale":"Optimize for efficiency without removing human oversight from decisions that affect people.","sources":[{"title":"CCAO-F exam guide v1.1 (November 2026)","url":"https://cc.sj-cdn.net/instructor/6nizmqk8tpzpfjvt6qmmav7rh/public/1794946524/Claude_Certified_Associate_-_Foundations_Exam_Guide.pdf","type":"exam_guide"}],"note":null,"volatile":false,"contentDate":"2026-11-24"}
);
